def _relative_directories(root):
    """Relative paths of every DIRECTORY entry observed under the selected root (CR-25).

    This is the admitted directory observation the instrument already holds. It is the anchor source for
    pruned trees; it is NOT a descent. A directory inside a pruned tree maps to the same outermost anchor,
    so listing it adds no anchor and discloses nothing about the tree contents."""
    base = root.rstrip('/') + '/'
    return sorted(p[len(base):] for p, e in fs.items()
                  if e.get('kind') == 'dir' and p.startswith(base))

def _unreadable_pruned_anchors(root):
    """Pruned anchors whose OWN directory entry could not be read (`aclUnreadable`, modelling

    EACCES/ENOTSUP on the ACL read). The anchor stays known and reported; its marker count becomes null
    with basis `not-enumerated`, because a count drawn from a directory whose own observation failed is
    not an observation. Only the anchor entry itself is consulted - never its contents."""
    base = root.rstrip('/') + '/'
    cargo = DD.cargo_roots_from_markers(_relative_marker_paths(root))
    out = set()
    for p, e in fs.items():
        if e.get('kind') != 'dir' or not p.startswith(base) or not e.get('aclUnreadable'):
            continue
        hit = DD.classify_path(p[len(base):], cargo)
        if hit is not None and hit[0] == p[len(base):]:
            out.add(hit[0])
    return out

